import { sql, type Kysely } from 'kysely';

/**
 * Core schema: everything the Mongo version stored, as relational tables.
 *
 * Design notes
 *  - Entity ids are UUIDs generated by the application (see domain/shared/ids.ts).
 *  - A source owns immutable catalog "revisions": a sync writes revision N+1 next to N, then
 *    flips `sources.revision` with a compare-and-set (readers always pin a revision).
 *  - Catalog rows are keyed (source_id, revision, key); deleting a source cascades.
 *  - Secrets (credentials, stream URLs) are stored already encrypted by the application.
 */
export async function up(db: Kysely<unknown>): Promise<void> {
  await sql
    .raw(
      `
CREATE TABLE users (
  id               uuid        PRIMARY KEY,
  token_hash       text        NOT NULL UNIQUE,
  legacy_secret_id text        UNIQUE,
  created_at       timestamptz NOT NULL DEFAULT now(),
  last_seen_at     timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE sources (
  id                   uuid        PRIMARY KEY,
  owner_id             uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  name                 text        NOT NULL CHECK (char_length(name) BETWEEN 1 AND 120),
  type                 text        NOT NULL CHECK (type IN ('m3u_url', 'm3u_file', 'xtream')),
  origin               jsonb       NOT NULL,
  credential           text,
  revision             integer     NOT NULL DEFAULT 0,
  epg_version          integer     NOT NULL DEFAULT 0,
  stats                jsonb       NOT NULL DEFAULT '{"live":0,"movies":0,"series":0,"episodes":0,"groups":0,"unplayable":0,"catchup":0,"epgMapped":0}',

  sync_status          text        NOT NULL CHECK (sync_status IN ('idle', 'queued', 'running', 'failed')),
  sync_stage           text,
  sync_auto            boolean     NOT NULL DEFAULT true,
  sync_interval_hours  integer     NOT NULL DEFAULT 6,
  sync_last_attempt_at timestamptz,
  sync_last_success_at timestamptz,
  sync_next_at         timestamptz,
  sync_error           jsonb,
  sync_failures        integer     NOT NULL DEFAULT 0,
  sync_rerun           boolean     NOT NULL DEFAULT false,
  lease_owner          text,
  lease_until          timestamptz,

  health               jsonb       NOT NULL DEFAULT '{"state":"unknown","checkedAt":null,"latencyMs":null,"unstableStreams":0,"offlineStreams":0,"message":null}',
  account              jsonb,
  epg_urls             text[]      NOT NULL DEFAULT '{}',
  warnings             jsonb       NOT NULL DEFAULT '[]',
  warning_count        integer     NOT NULL DEFAULT 0,
  format               text        NOT NULL DEFAULT '',
  encoding             text        NOT NULL DEFAULT '',
  xtream_candidate     boolean     NOT NULL DEFAULT false,
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX sources_owner_idx ON sources (owner_id, created_at);
CREATE INDEX sources_sync_idx  ON sources (sync_status, sync_next_at);

CREATE TABLE live_channels (
  source_id         uuid    NOT NULL REFERENCES sources (id) ON DELETE CASCADE,
  revision          integer NOT NULL,
  key               text    NOT NULL,
  position          integer NOT NULL,
  name              text    NOT NULL,
  groups            text[]  NOT NULL DEFAULT '{}',
  logo              text,
  tvg_id            text,
  tvg_name          text,
  kind              text    NOT NULL,
  unplayable_reason text,
  locator           text,
  catchup           jsonb,
  adult             boolean NOT NULL DEFAULT false,
  xtream            jsonb,
  added_at          timestamptz,
  epg               jsonb,
  name_key          text    NOT NULL DEFAULT '',
  search_tokens     text[]  NOT NULL DEFAULT '{}',
  PRIMARY KEY (source_id, revision, key)
);
CREATE INDEX live_channels_order_idx    ON live_channels (source_id, revision, position);
CREATE INDEX live_channels_name_key_idx ON live_channels (source_id, revision, name_key);

CREATE TABLE movies (
  source_id     uuid             NOT NULL REFERENCES sources (id) ON DELETE CASCADE,
  revision      integer          NOT NULL,
  key           text             NOT NULL,
  position      integer          NOT NULL,
  name          text             NOT NULL,
  year          integer,
  groups        text[]           NOT NULL DEFAULT '{}',
  poster        text,
  rating        double precision,
  genres        text[]           NOT NULL DEFAULT '{}',
  duration_secs double precision,
  plot          text,
  kind          text             NOT NULL,
  locator       text,
  adult         boolean          NOT NULL DEFAULT false,
  xtream        jsonb,
  added_at      timestamptz,
  search_tokens text[]           NOT NULL DEFAULT '{}',
  PRIMARY KEY (source_id, revision, key)
);
CREATE INDEX movies_order_idx ON movies (source_id, revision, position);
CREATE INDEX movies_added_idx ON movies (source_id, revision, added_at DESC);

CREATE TABLE series (
  source_id          uuid             NOT NULL REFERENCES sources (id) ON DELETE CASCADE,
  revision           integer          NOT NULL,
  key                text             NOT NULL,
  position           integer          NOT NULL,
  name               text             NOT NULL,
  year               integer,
  groups             text[]           NOT NULL DEFAULT '{}',
  cover              text,
  rating             double precision,
  genres             text[]           NOT NULL DEFAULT '{}',
  plot               text,
  adult              boolean          NOT NULL DEFAULT false,
  xtream             jsonb,
  added_at           timestamptz,
  search_tokens      text[]           NOT NULL DEFAULT '{}',
  details_fetched_at timestamptz,
  PRIMARY KEY (source_id, revision, key)
);
CREATE INDEX series_order_idx ON series (source_id, revision, position);
CREATE INDEX series_added_idx ON series (source_id, revision, added_at DESC);

CREATE TABLE episodes (
  source_id     uuid             NOT NULL REFERENCES sources (id) ON DELETE CASCADE,
  revision      integer          NOT NULL,
  series_key    text             NOT NULL,
  key           text             NOT NULL,
  season        integer          NOT NULL,
  episode       integer          NOT NULL,
  title         text             NOT NULL,
  plot          text,
  duration_secs double precision,
  still         text,
  air_date      text,
  kind          text             NOT NULL,
  locator       text,
  xtream        jsonb,
  PRIMARY KEY (source_id, revision, series_key, key)
);
CREATE INDEX episodes_order_idx ON episodes (source_id, revision, series_key, season, episode);

CREATE TABLE notifications (
  id         uuid        PRIMARY KEY,
  owner_id   uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  type       text        NOT NULL,
  severity   text        NOT NULL,
  title      text        NOT NULL,
  body       text,
  link       text,
  read       boolean     NOT NULL DEFAULT false,
  dedupe_key text,
  created_at timestamptz NOT NULL
);
CREATE INDEX notifications_owner_idx   ON notifications (owner_id, created_at DESC);
CREATE INDEX notifications_created_idx ON notifications (created_at);
-- At most one UNREAD notification per dedupe key: a new event refreshes it instead of stacking.
CREATE UNIQUE INDEX notifications_dedupe_unread_uq ON notifications (owner_id, dedupe_key) WHERE read = false AND dedupe_key IS NOT NULL;

CREATE TABLE schedules (
  job         text        PRIMARY KEY,
  next_run_at timestamptz,
  last_run_at timestamptz,
  last_error  text,
  lease_owner text,
  lease_until timestamptz
);
`,
    )
    .execute(db);
}
